'use strict';
// 0.5: persistent random activity invitations and transport-led city specialities.
const ACTIVITY_WEIGHTS=[[50,27,13,6,3,1],[44,28,15,7,4,2],[40,28,16,8,5,3],[36,28,17,9,6,4],[32,28,18,10,7,5]];
const ACTIVITY_TYPES=[null,null,'bus','emu','rail','air'];
const VEHICLE_BASE={bus:180,emu:560,rail:900,air:1600};
function activityState(){return S.activityCards??={next:S.day>=22?S.day+1:22,seq:0,offers:[],active:null,history:[],debt:0,bonuses:{hub:0,bus:0,emu:0,rail:0,air:0}};}
function activityWeights(day=S.day){return ACTIVITY_WEIGHTS[day<88?0:Math.min(4,1+Math.floor((day-88)/30))];}
function industryDiscount(){return Math.max(0,...realCities().filter(c=>!c.dormant&&c.shape===3&&c.size>=1).map(c=>c.size===2?.1:.05));}
function industryPrice(n){return Math.ceil(n*(1-industryDiscount()));}
// Accessors keep every existing shop, quote and actual payment on the same current price.
for(let t of Object.keys(VEHICLE_BASE))Object.defineProperty(TYPES[t],'vehicle',{configurable:true,get:()=>industryPrice(VEHICLE_BASE[t])});
const draftBeforeCards=draftCost;draftCost=function(){let q=draftBeforeCards();if(q.cash){q.baseConstruction=q.cash-q.vehicle;q.cash=industryPrice(q.baseConstruction)+q.vehicle;q.industrialDiscount=industryDiscount();}return q;};
const bridgePriceBeforeCards=bridgePrice;bridgePrice=function(...a){return industryPrice(bridgePriceBeforeCards(...a));};
for(let [get,set] of [[()=>upgradeQuote,f=>upgradeQuote=f],[()=>bridgeUpgradeQuote,f=>bridgeUpgradeQuote=f]]){let before=get();set(function(...a){let q=before(...a);return q?{...q,price:industryPrice(q.price)}:q;});}
const carBeforeCards=carPrice;carPrice=function(v){return industryPrice(carBeforeCards(v));};
const fareBeforeCards=tripFare;tripFare=function(p,c){return Math.round(fareBeforeCards(p,c)*(c.shape===2?1.2:1)*100)/100;};
function hubApproachFactor(v,l,a,b,t){if(v.type==='air'||!b.hub||!serves(v,l,v.index+v.dir))return 1;return (1-t)*Math.hypot(a.x-b.x,a.y-b.y)<=80?1.15:1;}
const advanceBeforeCards=advanceVehicleProgress;advanceVehicleProgress=function(v,l,a,b,dt){let t=v.t;for(let left=dt;left>0&&t<1;){let h=Math.min(.025,left);t=advanceBeforeCards({...v,t},l,a,b,h*hubApproachFactor(v,l,a,b,t));left-=h;}return t;};
serviceTravelTime=function(v,l,index,dir){let a=S.cities[l.stops[index]],b=S.cities[l.stops[index+dir]],sample={...v,index,dir},sum=0;for(let i=0;i<24;i++){let t=(i+.5)/24;sum+=1/(trainSpeedFactor(sample,l,a,b,t)*hubApproachFactor(sample,l,a,b,t));}return edgeTime(a,b,l.type)*sum/24;};
function activityRewardChoices(){let s=activityState();return ['bus','emu','rail','air'].filter(t=>S.unlocked.includes(t)&&s.bonuses[t]<3).map(t=>({type:t,label:TYPES[t].name+'线路上限＋1'})).concat(s.bonuses.hub<2?[{type:'hub',label:'枢纽上限＋1'}]:[]);}
function activityEligible(star){return star===1||star===6?star===1||S.unlocked.includes('rail')&&activityRewardChoices().length>0:S.unlocked.includes(ACTIVITY_TYPES[star]);}
function activityPassenger(card,origin){let c=S.cities[card.host];return {...eventPassenger({id:card.id},origin,c.id),cardId:card.id};}
function activitySources(host){return realCities().filter(c=>!c.dormant&&c.id!==host&&plan(c.id,{origin:c.id,eventId:'activity-preview',dest:host})).map(c=>c.id);}
function drawActivityStar(){let eligible=activityWeights().map((weight,i)=>({star:i+1,weight})).filter(x=>activityEligible(x.star)),r=Math.random()*eligible.reduce((n,x)=>n+x.weight,0);for(let x of eligible){r-=x.weight;if(r<0)return x.star;}return 1;}
function makeActivityCard(star,host,sources){let s=activityState(),reward=star===6?activityRewardChoices()[Math.floor(Math.random()*activityRewardChoices().length)]:null;
let seats=S.vehicles.filter(v=>!v.retired).reduce((n,v)=>n+vehCap(v),0),total=Math.round(Math.max(12,Math.min(18+star*6,seats*(.65+star*.08))));let titles=['社区交流日','旅游节','商务峰会','工业展会'];return {id:'activity-'+(++s.seq),star,host,sources,title:titles[S.cities[host].shape],total,goal:Math.ceil(total*.8),goodRatio:star>=4?.8:0,waitLimit:120,prepare:star<=2?3:star<=4?4:5,duration:8+Math.floor(star/2),bonus:80+star*50,fine:30+star*30,scoreLoss:star===6?15:0,reward,vehicle:ACTIVITY_TYPES[star]||null};}
function generateActivityOffers(){let s=activityState(),hosts=realCities().filter(c=>!c.dormant).map(c=>({c,sources:activitySources(c.id)})).filter(x=>x.sources.length);if(!hosts.length){s.next=S.day+3;return false;}s.offers=Array.from({length:3},(_,i)=>{let x=hosts[(Math.floor(Math.random()*hosts.length)+i)%hosts.length];return makeActivityCard(s.seq===0&&i===0?1:drawActivityStar(),x.c.id,x.sources);});save();return true;}
function activityRewardText(e){return '¥'+e.bonus+' · 满意度＋'+(5+e.star)+(e.vehicle?' · '+TYPES[e.vehicle].name+'×1':e.reward?' · '+e.reward.label:'');}
function activityCardHTML(e,index=0){let revealed=!!e.revealed;return `<article id="card-${e.id}" class="activity-slot stars-${e.star}${revealed?' is-revealed':''}" style="--deal:${index}" aria-label="活动邀请 ${index+1}"><div class="activity-flipper"><button class="activity-back" onclick="revealActivity('${e.id}')" ${revealed?'tabindex="-1" aria-hidden="true"':'aria-label="翻开第'+(index+1)+'张活动卡"'}><span class="card-back-top">EAST COAST · INVITATION</span><span class="card-sigil" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M30 81V39l30-17 30 17v42L60 98Z"/><path d="M30 81 60 64l30 17M60 22v42M30 39l30 17 30-17"/><circle cx="60" cy="64" r="10"/><circle cx="30" cy="39" r="4"/><circle cx="90" cy="81" r="4"/></svg></span><span class="card-back-title">城市的下一种可能</span><span class="card-back-sub">翻开邀请 · 发现机遇</span><span class="card-back-number">0${index+1} / 03</span></button><div class="activity-card activity-front" ${revealed?'':'inert aria-hidden="true"'}><div class="card-rarity"><span>${'★'.repeat(e.star)}</span><small>${e.star===6?'传奇邀请':e.star===5?'稀有邀请':e.star===1?'普通活动':'重点活动'}</small></div><span class="card-feature">${escapeHTML(FEATURES[S.cities[e.host].shape].name)} · 城市计划</span><h3>${escapeHTML(e.title)}</h3><b class="card-city">${escapeHTML(S.cities[e.host].name)}</b><div class="card-stats"><span><b>${e.prepare}</b>天筹备</span><span><b>${e.goal}</b>人送达</span><span><b>${e.duration}</b>天期限</span></div><p class="card-sources">客源：${e.sources.map(id=>escapeHTML(S.cities[id].name)).join('、')}<br>计划 ${e.total} 人${e.goodRatio?' · 80%送达者候车≤120秒':''}</p><div class="card-reward"><small>完成奖励</small><p>${activityRewardText(e)}</p></div><p class="card-risk">未完成：最高罚款 ¥${e.fine}${e.scoreLoss?' · 服务评分最多−'+e.scoreLoss:''}<br><small>按目标缺口扣罚，票款另计。</small></p><button class="primary card-accept" onclick="acceptActivity('${e.id}')">承接这份邀请 <span>↗</span></button></div></div><div class="card-reveal-fx" aria-hidden="true"><i class="card-halo"></i>${Array.from({length:12},(_,i)=>`<i class="card-spark" style="--spark:${i};--sx:${8+i*23%84}%;--sy:${12+i*31%72}%"></i>`).join('')}</div></article>`;}
function revealActivity(id){let e=activityState().offers.find(e=>e.id===id);if(!e||e.revealed)return;e.revealed=true;save();let card=$('card-'+id);if(card){let back=card.querySelector('.activity-back'),front=card.querySelector('.activity-front');if(back){back.setAttribute('aria-hidden','true');back.tabIndex=-1;}if(front){front.removeAttribute('inert');front.removeAttribute('aria-hidden');}card.classList.add('is-revealed','is-revealing');let accept=card.querySelector('.card-accept');accept?.focus({preventScroll:true});}let status=$('activity-reveal-status');if(status)status.textContent=e.star+'星 · '+S.cities[e.host].name+' · '+e.title+' · 奖励 '+activityRewardText(e);}
function revealAllActivities(){for(let e of activityState().offers)revealActivity(e.id);}

function showActivityCards(){let s=activityState(),e=s.active;openModal(`<div class="modal-head"><div><span class="eyebrow">CITY ACTIVITIES / 0.5</span><h2>${e?'活动进行中':'随机城市活动'}</h2></div><button class="close" onclick="closeModal()">×</button></div>${e?`<section class="infra-card"><h3>${'★'.repeat(e.star)} ${escapeHTML(e.title)} · ${escapeHTML(S.cities[e.host].name)}</h3><p>${S.day<e.start?'准备中，还需 '+(e.start-S.day).toFixed(1)+' 天':'运输中，剩余 '+Math.max(0,e.end-S.day).toFixed(1)+' 天'}<br>已出发 ${e.spawned}/${e.total} · 已送达 ${e.delivered}/${e.goal}<br>候车合格 ${e.good}/${e.delivered}（${e.goodRatio?'要求80%':'无额外比例要求'}）</p><p>成功：${activityRewardText(e)}<br>失败：最高 ¥${e.fine}${e.scoreLoss?'，服务评分最多−'+e.scoreLoss:''}</p><button onclick="closeModal();openCity(${e.host})">定位举办城市</button></section>`:s.offers.length?`<div class="activity-deck-intro"><span class="eyebrow">THREE INVITATIONS · ONE CHOICE</span><h3>下一站，会有什么机遇？</h3><p>点击翻牌，查看三份邀请后选择一份承接。翻牌不会接取活动，查看时模拟暂停。<span class="card-swipe-hint">左右滑动查看另外两张</span></p></div><div id="activity-reveal-status" class="sr-only" role="status" aria-live="polite"></div><div class="activity-grid" role="group" aria-label="三张活动邀请">${s.offers.map(activityCardHTML).join('')}</div><div class="activity-deck-actions"><button onclick="revealAllActivities()">全部翻开</button><button onclick="skipActivityOffers()">暂不承接 · 5～7天后再来</button></div>`:`<p>首次第22天开放。下次邀请约 ${Math.max(0,s.next-S.day).toFixed(1)} 天后出现；活动结束后间隔8～12天。</p>`}<p>待缴活动罚款 ¥${s.debt.toFixed(2)}。未付部分从后续收入补缴。奖励车辆进入库存；线路最多额外＋3/车型，枢纽最多额外＋2，名额仍需自费建设。</p><h3>最近结算</h3>${s.history.slice(0,8).map(x=>`<p>${'★'.repeat(x.star)} ${escapeHTML(S.cities[x.host]?.name||'城市')} · ${x.success?'成功：'+activityRewardText(x):'失败：罚款 ¥'+x.penalty+'，评分−'+x.scorePenalty} · 送达${x.delivered}/${x.goal}</p>`).join('')||'<p>暂无记录</p>'}`);}
function acceptActivity(id){let s=activityState(),e=s.offers.find(x=>x.id===id);if(!e||s.active||S.event)return;let sources=e.sources.filter(id=>S.cities[id]&&!S.cities[id].dormant);if(!sources.length||S.cities[e.host]?.dormant)return toast('客源或举办城市已变化，请重新选择');s.active={...e,sources,start:S.day+e.prepare,end:S.day+e.prepare+e.duration,spawned:0,delivered:0,good:0};s.offers=[];save();showActivityCards();}
function skipActivityOffers(){let s=activityState();if(s.active||!s.offers.length)return;s.offers=[];s.next=S.day+rand(5,7);save();closeModal();}
function payActivityDebt(){let s=activityState(),paid=cashRound(Math.min(S.points,s.debt));if(paid>0){spend(paid,'activityFines','活动违约罚款');s.debt=cashRound(s.debt-paid);}}
const creditBeforeCards=credit;credit=function(...args){creditBeforeCards(...args);if(S.activityCards?.debt)payActivityDebt();};
function applyActivityScore(c,amount){let svc=cityService(c);let old=svc.activityEffect,left=old?old.amount*Math.max(0,Math.min(1,(old.until-S.day)/14)):0;svc.activityEffect={amount:Math.max(-20,Math.min(15,left+amount)),until:S.day+14};if(svc.score!==null){svc.score=Math.max(0,Math.min(100,svc.score+svc.activityEffect.amount-left));svc.rating=svc.score>=85?'优':svc.score>=70?'良':svc.score>=50?'一般':'差';}}
function settleActivity(){let s=activityState(),e=s.active;if(!e||S.day<e.end)return;let goodTarget=e.goodRatio?Math.ceil(e.goal*e.goodRatio):0,progress=Math.min(1,e.delivered/e.goal,goodTarget?e.good/goodTarget:1),success=e.delivered>=e.goal&&(!e.goodRatio||e.good/Math.max(1,e.delivered)>=e.goodRatio);if(!success&&progress===1)progress=.95;
let penalty=success?0:Math.ceil(e.fine*(1-progress)),scorePenalty=success?0:Math.ceil(e.scoreLoss*(1-progress));s.active=null; // Consume before any rewards: repeated settlement cannot grant twice.
if(success){credit(e.bonus,'events','随机活动完成奖金');applyActivityScore(S.cities[e.host],5+e.star);if(e.vehicle){S.inventory[e.vehicle]++;addStockAsset(e.vehicle,{cars:isTrain(e.vehicle)?2:1,investment:0});}if(e.reward){s.bonuses[e.reward.type]++;if(e.reward.type!=='hub')S.limits[e.reward.type]++;}}else{s.debt=cashRound(s.debt+penalty);payActivityDebt();if(scorePenalty)applyActivityScore(S.cities[e.host],-scorePenalty);}
let keep=p=>p.cardId!==e.id;for(let c of S.cities)c.q=c.q.filter(keep);for(let v of S.vehicles)v.people=v.people.filter(keep);s.history.unshift({...e,success,penalty,scorePenalty,day:S.day});s.history=s.history.slice(0,20);s.next=S.day+rand(8,12);save();toast(success?'活动完成 · '+activityRewardText(e):'活动未达标 · 罚款 ¥'+penalty+(scorePenalty?' · 城市服务评分−'+scorePenalty:''));}
const completeBeforeCards=completeTrip;completeTrip=function(p,dest){completeBeforeCards(p,dest);let e=activityState().active;if(p.cardId&&e?.id===p.cardId&&dest.id===e.host&&S.day>=e.start&&S.day<=e.end){e.delivered++;if(p.wait<=e.waitLimit*(S.cities[p.origin]?.shape===1?1.25:1))e.good++;}};
function updateActivityCards(){let s=activityState(),e=s.active;if(e){if(S.day>=e.end){settleActivity();return;}if(S.day>=e.start){let desired=Math.min(e.total,Math.floor(e.total*Math.min(1,(S.day-e.start)/Math.max(1,e.duration-3))));while(e.spawned<desired){let id=e.sources[e.spawned%e.sources.length];if(S.cities[id]&&!S.cities[id].dormant)S.cities[id].q.push(activityPassenger(e,id));e.spawned++;}}}else if(!s.offers.length&&!S.event&&S.day>=s.next&&generateActivityOffers())showActivityCards();}
const worldBeforeCards=updateWorld;updateWorld=function(...a){worldBeforeCards(...a);updateActivityCards();};
const opsBeforeCards=showOperations;showOperations=function(){opsBeforeCards();let s=activityState();if(!S.event)$('modal-content').innerHTML=$('modal-content').innerHTML.replace(/<section class="infra-card"><h3>♫ 商演活动<\/h3>[\s\S]*?<\/section>/,'');$('modal-content').innerHTML=`<section class="infra-card"><h3>随机城市活动 · ${s.active?'进行中':s.offers.length?'三张邀请待选择':'等待邀请'}</h3><button class="primary" onclick="showActivityCards()">${s.active?'查看活动进度':s.offers.length?'选择活动卡片':'活动规则 / 记录'}</button></section>`+$('modal-content').innerHTML.replace('普通乘客仍按颜色＋形状匹配。活动观众等待超时影响活动收益，不直接扣生命；普通乘客的等待压力仍需照顾。','普通乘客按颜色＋形状匹配。随机活动游客指定城市，活动失败统一扣罚；公共服务合同沿用原规则。');};
// New invitations replace manual concert creation; already accepted legacy concerts finish normally.
chooseConcert=function(){showActivityCards();};startConcert=function(){showActivityCards();};
const uiBeforeCards=updateUI;updateUI=function(){uiBeforeCards();let s=activityState();if(s.offers.length)$('notice').textContent='★ 三张城市活动邀请 · 运营中心选择';else if(s.active)$('notice').textContent='★ '+S.cities[s.active.host].name+' · '+(S.day<s.active.start?'活动准备中':'送达 '+s.active.delivered+'/'+s.active.goal);};
const operationsButton=$('operations');operationsButton.onclick=()=>showOperations();
const cityBeforeCards=showCityEconomy;showCityEconomy=function(id){cityBeforeCards(id);let c=S.cities[id],svc=cityService(c);$('modal-content').innerHTML+=`<section class="infra-card"><h3>城市特色 / 活动口碑</h3><p>${c.shape===1?'旅游：本城候车耐心＋25%，满员压力上限225秒，居民候车评价阈值同步放宽。':c.shape===3?'工业：接入且中型后全网路桥新建、升级及车辆/车厢采购−5%，大型−10%，多城取最高、不叠加；其他城市建筑与维修费保持原价。':c.shape===2?'商业金融：运抵本城的票款＋20%，中转换乘不重复加价。':'居住：为其他城市提供通勤客流。'}<br>当前全网工业优惠 ${Math.round(industryDiscount()*100)}%。${svc.activityEffect?'活动口碑修正随14天逐渐消退。':''}${c.hub?'<br>枢纽：容量×2、换乘准备−30%、进站80范围内速度＋15%，飞机不生效。':''}</p></section>`;};
const financeBeforeCards=showFinance;showFinance=function(){financeBeforeCards();$('modal-content').innerHTML+=`<p>随机活动罚款已缴 ¥${S.ledger.activityFines||0} · 待缴 ¥${activityState().debt.toFixed(2)}。商业金融目的地票款＋20%。工业优惠已计入报价。</p>`;};
const shopBeforeCards=shop;shop=function(){shopBeforeCards();$('modal-content').innerHTML+=`<p>工业城市采购优惠 ${Math.round(industryDiscount()*100)}%，以上车辆及车厢价格已包含优惠。</p>`;};
const freshBeforeCards=fresh;fresh=function(){let s=freshBeforeCards();s.activityCards={next:22,seq:0,offers:[],active:null,history:[],debt:0,bonuses:{hub:0,bus:0,emu:0,rail:0,air:0}};return s;};
const loadBeforeCards=load;load=function(){let ok=loadBeforeCards();if(ok){activityState();save();}return ok;};
FEATURES[2].name='商业金融';
activityState();save();

const helpBeforeCards=help;help=function(){helpBeforeCards();$('modal-content').innerHTML+='<section class="infra-card"><h3>0.5 城市活动</h3><p>第22天起随机三选一。1星奖金，2～5星另送大巴/动车/高铁/飞机，6星增加显示的线路或枢纽名额。第88天起每30天提高高星概率，第178天封顶。承接后3～5天准备，完成加满意度，失败按缺口罚款，6星另扣服务评分；口碑修正在14天内消退。奖励车辆零购入成本。商业金融目的地票款＋20%；工业中/大城路桥及车辆优惠5%/10%，多城不叠加。</p></section>';};
$('help').onclick=()=>help();

concertAvailable=function(){return S.day>=22;};
const eventHistoryBeforeCards=showEventHistory;showEventHistory=function(){showActivityCards();};
const drawMarkersBeforeCards=drawEventMarkers;drawEventMarkers=function(){drawMarkersBeforeCards();let e=activityState().active;if(!e)return;let c=S.cities[e.host];roundBody(c.x-48,c.y-113-c.size*9,96,21,6,'#fff4e5','#d2ad76',.9);text('★ '+(S.day<e.start?'准备':e.delivered+'/'+e.goal),c.x,c.y-99-c.size*9,10,'#a27145');};

const loadBeforeCityOpening=load;load=function(){let ok=loadBeforeCityOpening();if(ok){initializeCityOpeningTimers();save();}return ok;};
const uiBeforeCityOpening=updateUI;updateUI=function(){uiBeforeCityOpening();let urgent=realCities().filter(c=>c.dormant&&cityOpeningRemaining(c)<=10).sort((a,b)=>a.openingAt-b.openingAt)[0];if(urgent)$('notice').textContent=urgent.name+' · 即将开放 '+cityOpeningRemaining(urgent)+'s · 可暂停安排线路';};
const helpBeforeCityOpening=help;help=function(){helpBeforeCityOpening();$('modal-content').innerHTML+='<p>0.5 新城开放：所有待接入城市（含远城、跨河城市）发现后30个游戏模拟秒自动开始产生游客，最后10秒显示橙色提醒。提前接通立即运营，客流逐渐增加；暂停、卡片、商店与拉线规划期间不计时。远城未接通前不会继续向更远方向刷新。</p>';};
initializeCityOpeningTimers();save();
